import bpy, os
# apply modifiers and transforms on model meshes
exclude={"Ground","Camera","Key","Fill","Rim"}
model=[o for o in bpy.data.objects if o.type=='MESH' and o.name not in exclude]
bpy.ops.object.select_all(action='DESELECT')
for o in model:
    bpy.ops.object.select_all(action='DESELECT')
    o.select_set(True); bpy.context.view_layer.objects.active=o
    for mod in list(o.modifiers):
        try: bpy.ops.object.modifier_apply(modifier=mod.name)
        except Exception as e: print("mod fail",o.name,e)
    try: bpy.ops.object.transform_apply(location=False, rotation=True, scale=True)
    except Exception as e: print("xform fail",o.name,e)
# select model for export
bpy.ops.object.select_all(action='DESELECT')
for o in model: o.select_set(True)
bpy.context.view_layer.objects.active=model[0]
out=os.path.join(os.getcwd(),"output","robie_the_banker.glb")
bpy.ops.export_scene.gltf(filepath=out, export_format='GLB', use_selection=True, export_draco_mesh_compression_enable=False)
result={"out":out,"size":os.path.getsize(out),"count":len(model)}

